package com.example.myapplication.Kotlin
fun main(array: Array<String>) {
    // 산술 연산자
    var a = 10 + 1
    var b = 10 - 1
    var c = 1 * 9
    var d = 20 / 3
    var e = 20 % 3
    println(a)
    println(b)
    println(c)
    println(d)
    println(e)
    // 대입 연산자
    val f = 5
//    val 5 = f
    //복합 대입 연산자
    a += 10
    b -= 10
    c *= 3
    d /= 4
    e %= 2
    println()
    println(a)
    println(b)
    println(c)
    println(d)
    println(e)
    //증감 연산자
    a++
    b--
    println()
    println(a)
    println(b)
    // 비교연산자
    val g = a > b
    val h = a == b
    val i = !h
    val l = i != h
    println(g)
    println(h)
    println(i)
    println(l)
    // 논리 연산자
    val j = h && i
    val k = h || i
    println()
    println(j)
    println(k)
}
08.Control_Flow.kt
package com.example.myapplication.Kotlin
// 08. 제어 흐름
// - if, else
fun main(args: Array<String>) {
    val a: Int = 5
    val b: Int = 10
    // if/else 사용 하는 방법 (1)
    if (a > b) {
        println("a 가 b 보다 크다")
    } else {
        println("a 가 b 보다 작다")
    }
    // if/else 사용 하는 방법 (2)
    if (a > b) {
        println("a 가 b 보다 크다")
    }
    // if/else/else if 사용 하는 방법 (2)
    if (a > b) {
        println("a 가 b 보다 크다")
    } else if (a < b) {
        println("a 가 b 보다 작다")
    } else if (a == b) {
        println("a 와 b는 같다")
    } else {
    }
    // 값을 리턴하는 if 사용방법
    val max = if (a > b) {
        a //5
    } else {
        b //10
    }
    // 값을 리턴하는 if 사용방법(2)
    val max1 = if (a > b) a else b
    println()
    println(max)
}
