10.Control_Flow(2).kt
package com.example.myapplication.Kotlin
// 10 제어흐름
// When
fun main(args: Array<String>) {
    val value: Int = 1
    when (value) {
        1 -> println("value is 1")
        2 -> println("value is 2")
        3 -> println("value is 3")
        else -> println("I do not know value")
    }
    if (value == 1) println("value is 1")
    else if (value == 2) println("value is 2")
    else if (value == 3) println("value is 3")
    else println("I do not know value")
    val value2 = when (value) {
        1 -> 10
        2 -> 20
        3 -> 30
        else -> 100
    }
    println(value2)
}
11.Practice.kt
package com.example.myapplication.Kotlin
// 11. 제어흐름 실습
fun main(args: Array<String>) {
    val value: Int? = null
    when (value) {
        null -> println("value is null")
        else -> println("value is not null")
    }
    val value2: Boolean? = null
    // when 구문은 조건으로 갖는 값의 모든 경우에 대응 해주는 것이 좋다
    when (value2) {
        true -> println("")
        false -> println("")
        null -> println("")
    }
    // 값을 리턴하는 when 구문의 경우 반듯이 값을 리턴해야 한다
    val value3 = when (value2) {
        true -> 1
        false -> 3
        else -> 4
    }
    // when 의 다양한 조건식 (1)
    val value4: Int = 10
    when (value4) {
        is Int -> {
            println("value4 is int")
        }
        else -> {
            println("value4 is not int")
        }
    }
    // when 의 다양한 조건식 (2)
    val value5: Int = 70
    when (value5) {
        in 60..70 -> {
            println("value is in 60-70")
        }
        in 70..80 -> {
            println("value is in 70-80")
        }
        in 80..90 -> {
            println("value is in 80-90")
        }
    }
}
