    class NetworkTask(
        val recyclerView: RecyclerView,
        val inflater: LayoutInflater,
    ) : AsyncTask<Any?, Any?, Array<PersonFromServer>>() {

        override fun onPostExecute(result: Array<PersonFromServer>?) {
            val adapter = PersonAdapter(result!!, inflater)
            recyclerView.adapter = adapter

            super.onPostExecute(result)
        }


        override fun doInBackground(vararg p0: Any?): Array<PersonFromServer> {
            val urlString: String = "http://mellowcode.org/json/students/"
            val url: URL = URL(urlString)
            val cononnection: HttpURLConnection = url.openConnection() as
                    HttpURLConnection

            cononnection.requestMethod = "GET"
            cononnection.setRequestProperty("Content-Type", "application/json")


            var buffer = ""
            if (cononnection.responseCode == HttpURLConnection.HTTP_OK) {
                val reader = BufferedReader(
                    InputStreamReader(
                        cononnection.inputStream,
                        "UTF-8"
                    )
                )
                buffer = reader.readLine()
            }
	    Log.d("conn","buffer : ${buffer}")

            val data = Gson().fromJson(buffer, Array<PersonFromServer>::class.java)

            Log.d("conn", "age : "+data[0].age)


            return data
        }
    }

    class PersonAdapter(
        val personList : Array<PersonFromServer>,
        val inflater: LayoutInflater
    ): RecyclerView.Adapter<PersonAdapter.ViewHolder>(){
        inner class ViewHolder(itemView: View): RecyclerView.ViewHolder(itemView){
            val name : TextView
            val age : TextView
            val intro : TextView

            init{
                name = itemView.findViewById(R.id.person_name)
                age = itemView.findViewById(R.id.person_age)
                intro = itemView.findViewById(R.id.person_ment)
            }
        }

        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
            val view = inflater.inflate(R.layout.itemview, parent, false)

            return ViewHolder(view)
        }

        override fun getItemCount(): Int {
            return personList.size
        }

        override fun onBindViewHolder(holder: ViewHolder, position: Int) {
            holder!!.name.setText(personList.get(position).name ?: "")
            holder!!.age.setText(""+personList.get(position).age!!.toInt())
            holder!!.intro.setText(personList.get(position).intro ?: "")

        }
    }


}
