package com.wook.sharedpreference

import android.content.Context
import android.content.SharedPreferences
import androidx.appcompat.app.AppCompatActivity
import android.os.Bundle
import android.util.Log
import kotlinx.android.synthetic.main.activity_main.*

class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        //SHaredPreference
        //val sharedPreference = getSharedPreferences("sp1", Context.MODE_PRIVATE)

        //Mode
        // - MODE_PRIVATE : 생성한 application에서만 사용가능
        // - Mode_WORLD_READABLE : 다른 application 사용가능 -> 읽을 수만 있다.
        // - MODE_WORLD_WRITEABLE : 다른 application 사용 가능 -> 기록도 가능
        // - MODE_MULTI_PROCESS: 이미 호출되어 사용중인지 체크
        // - MODE_APPEND : 기존 preference에 신규로 추가



        //sql1 이라는 SharedPreference
        // (Key, Value) -> ("Hello", "안녕하세요")
        //sp2 -> SharedPreference
        // (Key,value) -> ("Hello", "안녕하세요.!!")


        //데이터 불러오기
        loadBtn.setOnClickListener {
            // SharedPreference에 값을 불러 오는 작업
            valsharedPreference = getSharedPreferences("sp1",Context.MODE_PRIVATE)
            val value1 = sharedPreference.getString("hello","데이터 없음")
            val value2 = sharedPreference.getString("goodBye","데이터 없음")
            Log.d("key-value", "value1:" + value1)
            Log.d("key-value", "value2: "+ value2)

        }
        // 커밋을 해준다음에 putString 부분을 주석처리하고 getString해도 데이터가 검색된다.
        // 그 이유는 db자체가 데이터를 저장하는 개념이기때문에 스토리지와 캐시를 clear 청소를 해줘야 데이터가
        // 사라진다.. sharedference 특징... 이면서 db에서 comit() 자주하면 안되는 이유다.

        //avb 에뮬에서 settings => apps => 해당 어플 => storage & cache clear 해줘야 된다.
        // 아레와 같이 코드를 작성하자.

        //데이터 저장
        saveBtn.setOnClickListener {
            val sharedPreference = getSharedPreferences("sp1", Context.MODE_PRIVATE)
            val editor : SharedPreferences.Editor = sharedPreference.edit()
            editor.putString("hello", "안녕하세요")
            editor.putString("goodBye", "안녕히가세요")

            editor.commit()
        }

        //특정 데이터만 지우기
        deleteBtn.setOnClickListener {
            val sharedPreference = getSharedPreferences("sp1",Context.MODE_PRIVATE)
            val editor = sharedPreference.edit()

            editor.remove("hello")
            editor.commit()
        }

        //전부다 지우기
        allClearBtn.setOnClickListener {
            val sharedPreference = getSharedPreferences("sp1",Context.MODE_PRIVATE)
            val editor = sharedPreference.edit()

            editor.clear()
            editor.commit()
        }
    }
}
