package com.wook.taplayout_pager

import androidx.appcompat.app.AppCompatActivity
import android.os.Bundle
import androidx.fragment.app.Fragment
import androidx.fragment.app.FragmentManager
import androidx.fragment.app.FragmentStatePagerAdapter
import com.google.android.material.tabs.TabLayout
import kotlinx.android.synthetic.main.activity_main.*

class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        //텝 만들기
        tabL.addTab(tabL.newTab().setText("ONE"))
        tabL.addTab(tabL.newTab().setText("TWO"))
        tabL.addTab(tabL.newTab().setText("THREE"))

        //페이저 만들기
        val pagerAdapter = PagerAdapter(supportFragmentManager,3)
        viewP.adapter = pagerAdapter

        //템레이아웃과 페이저 연결하기
        //텝에 셀렉트 리스너 장착
        tabL.addOnTabSelectedListener(object: TabLayout.OnTabSelectedListener{
            override fun onTabSelected(tab: TabLayout.Tab?) {
                viewP.currentItem = tab!!.position
            }
            override fun onTabUnselected(tab: TabLayout.Tab?) {
            }
            override fun onTabReselected(tab: TabLayout.Tab?) {
            }
        })
        //페이저에 체인지 리스너 장착
        //-> 페이저가 이동했을때 템을 이동시키는 코드
        viewP.addOnPageChangeListener(TabLayout.TabLayoutOnPageChangeListener(tabL))

    }
}

class PagerAdapter(
    fragmentManager :FragmentManager,
    val tabCount :Int
): FragmentStatePagerAdapter(fragmentManager){
    override fun getCount(): Int {
        return tabCount
    }

    override fun getItem(position: Int): Fragment {
        when(position){
            0->{
                return Fragment1()
            }
            1->{
                return Fragment2()
            }
            2->{
                return Fragment3()
            }
            else -> return Fragment1()
        }
    }

}

