package com.wook.tablayoutpage2

import androidx.appcompat.app.AppCompatActivity
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.viewpager.widget.PagerAdapter
import com.google.android.material.tabs.TabLayout
import kotlinx.android.synthetic.main.activity_main.*

class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        tabL.addTab(tabL.newTab().setText("ONE"))
        tabL.addTab(tabL.newTab().setText("TWO"))
        tabL.addTab(tabL.newTab().setText("THREE"))

        val adapter = ThreePageAdapter(LayoutInflater.from(this@MainActivity))
        viewP.adapter= adapter
        viewP.addOnPageChangeListener(TabLayout.TabLayoutOnPageChangeListener(tabL))

        tabL.addOnTabSelectedListener(object : TabLayout.OnTabSelectedListener{
            override fun onTabSelected(tab: TabLayout.Tab?) {
                viewP.setCurrentItem(tab!!.position)
            }

            override fun onTabUnselected(tab: TabLayout.Tab?) {
            }

            override fun onTabReselected(tab: TabLayout.Tab?) {

            }
        })
    }
}

class ThreePageAdapter(
    val layoutInflater: LayoutInflater
): PagerAdapter(){
    override fun instantiateItem(container: ViewGroup, position: Int): Any {
        //return super.instantiateItem(container, position)

        when(position){
            0->{
                val view = layoutInflater.inflate(R.layout.fragment1 , container, false)
                container.addView(view)
                return view
            }
            1->{
                val view = layoutInflater.inflate(R.layout.fragment2 , container, false)
                container.addView(view)
                return view
            }
            2->{
                val view = layoutInflater.inflate(R.layout.fragment3, container,false)
                container.addView(view)
                return view
            }else ->{
                val view = layoutInflater.inflate(R.layout.fragment1,container,false)
                container.addView(view)

                return view
            }
        }
    }

    override fun destroyItem(container: ViewGroup, position: Int, `object`: Any) {
        //super.destroyItem(container, position, `object`)
        container.removeView(`object` as View)
    }
    override fun getCount(): Int {
        return 3
    }

    override fun isViewFromObject(view: View, `object`: Any): Boolean {
        return view === `object` as View

        //== 1==1
        //=== 좀더 정확한 비교

    }
}
